// NVN front-end shell (stream S4b). The recompiled game finds NVN through `nvnBootstrapLoader(name)` and
// `nvnDeviceGetProcAddress(device, name)`; both return the guest address of an HLE thunk (dispatch.h) for every NVN entry point.
// Until an entry point is implemented its thunk is a logging stub: it logs the name, the arguments (decoded from the AArch64
// registers by the signature classes of the table) and the caller's guest address, counts the call, and returns 0.
//
// The table (src/gfx/nvn/nvn_table.inc) is generated by scripts/gen_nvn_table.py from the reverse-engineered NVN headers used
// against this exact game and from the NVN names other recompilation projects use; see docs/S4b.md for the sources and counts.
// A real implementation replaces a stub with register_impl(): the table entry then reports implemented.
//
// Signature classes (one character per argument, AArch64 calling convention):
//   p pointer / array / function pointer     i int, enum or bool (w register)    l 64-bit integer (x register)
//   f float (s register)   d double (d register)   S struct by value (the stub dumps raw registers)   ? unknown signature
// Return class: the same letters, v = void.
#pragma once
#include <cstddef>
#include <cstdint>
#include <string>
#include <vector>

#include "nxrt/abi.h"

namespace nxrt::nvn {

enum SourceMask : uint8_t {
    kSrcPracticeMod = 1,   // nvn.h of the MP1R practice mod (reverse-engineered, used against this game)
    kSrcSmoSsbu = 2,       // names registered by smo-recomp / ssbu-recomp
    kSrcOther = 4,         // explicit extras (Wonder, LAS recomp)
};

struct Entry {
    const char* name;
    char ret;              // return class
    const char* args;      // argument classes, "" for none, "?" for unknown
    uint8_t sources;       // SourceMask bits
};

struct StructSize {
    const char* name;
    uint32_t size;
    uint8_t sources;
};

// ---- the table --------------------------------------------------------------------------------------------------------
size_t entry_count();
const Entry& entry_at(size_t index);
int entry_index(const char* name);                 // -1 when the name is not an NVN entry point
const StructSize* struct_sizes(size_t* count);     // NVN object sizes (NVNdevice 0x3000, NVNtexture 0xC0, ...)
uint32_t struct_size(const char* name);            // 0 when unknown

// ---- installation -----------------------------------------------------------------------------------------------------
// Registers the HLE thunks: `nvnBootstrapLoader`, `nvnDeviceGetProcAddress` and a logging stub for every other entry point.
// Idempotent. The module loader then resolves a guest import of any of these names to its thunk.
void install();
// Policy for a name that is not in the table (the real driver would return null for a name it does not know, but a game
// built for a newer driver may ask for one): Stub (default; logged as UNKNOWN NVN PROC) or Null. [nvn] unknown / NXRT_NVN_UNKNOWN.
enum class UnknownPolicy { Stub, Null };
void set_unknown_policy(UnknownPolicy p);
// Guest address of the thunk for a name (what nvnBootstrapLoader returns); 0 for a null answer.
uint64_t proc_address(const char* name);

// ---- implementing entry points ----------------------------------------------------------------------------------------
// Replaces the stub of an entry point by a real handler (called with the guest registers like any HLE function; read the
// arguments from x0.. / v0.., write the result to x0 / v0). False when the name is not in the table.
bool register_impl(const char* name, HleFn fn);
bool is_implemented(const char* name);
size_t implemented_count();

// ---- reporting --------------------------------------------------------------------------------------------------------
struct CallStat {
    const Entry* entry;
    uint64_t calls;
    bool implemented;
};
uint64_t entry_calls(size_t index);                // calls of the entry so far (stub or implemented)
uint64_t stub_calls_total();                       // calls that reached a logging stub
size_t stubs_called_distinct();                    // distinct entry points that were called while still stubs
std::vector<CallStat> called_entries();            // every entry with at least one call, most called first
// How many calls of each stub are logged at Info before it goes quiet ([nvn] log_first_calls, default 3); all calls are
// logged at Trace.
// Formats the arguments of a call as the stub logs them, e.g. "p=0x7a00001000 i=7 l=0x40". For tests and tools.
std::string describe_args(const Entry& e, const ::Ctx* c);
void reset_counters();                             // tests

}  // namespace nxrt::nvn
